def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    if key in cache:
                        return cache[key]
                    result = func(*args, **kwargs)
                    cache[key] = result
                    return result
            else:
                if key in cache:
                    return cache[key]
                result = func(*args, **kwargs)
                cache[key] = result
                return result
        return wrapper
    return decorator

