def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize != None:
        maxsize = abs(maxsize)
        if maxsize < 1:
            raise ValueError('maxsize must be greater than 0.')

    def decorating_function(user_function):
        @wraps(user_function)
        def wrapper(*args, **kwargs):
            cache_args = args
            cache_key = args if not typed else args[:len(args) - (args[-1] in args[:-1])]
            if isinstance(cache_args[-1], Hashable):
                cache_key = cache_args[:-1] + (cache_args[-1],)
            if cache_key in wrapper.cache:
                wrapper.cache.move_to_end(cache_key)
            else:
                if wrapper.cache_size >= maxsize:
                    wrapper.cache.popitem()
                wrapper.cache_size += 1
            result = user_function(*args, **kwargs)
            wrapper.cache[cache_key] = result
            return result
        wrapper.cache = {}
        wrapper.cache_size = 0
        return wrapper
    return decorating_function

