def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    from gubbins.declarant import Declaration, ITuple
    if output is None:
        output = []

    for arg in sequence:
        if isinstance(arg, Declaration):
            output.extend(arg.interfaces)
        elif isinstance(arg, ITuple):
            output.extend(_normalizeargs(arg, output))
        else:
            output.append(arg)

    return output

