def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    # Check if all required digests are present in the manifest_files
    missing_digests = set(manifest_files) - set(digests_used.keys())
    if missing_digests:
        raise MissingDigestError(f"The following digests are missing in the manifest files: {missing_digests}")

