def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    logical_path_map = {}

    if version not in inventory:
        raise ValueError(f"Version {version} not found in inventory")

    for logical_path, file_info in inventory[version].items():
        content_files = set()
        for file_type, file_list in file_info.items():
            content_files.update(file_list)
        logical_path_map[logical_path] = content_files

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Validate fixity structure
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")

    # Check if fixity contains required keys
    required_keys = {'checksum', 'file', 'method'}
    for key in required_keys:
        if key not in fixity:
            raise ValueError(f"Fixity block missing required key: {key}")

    # Validate file references
    if fixity['file'] not in manifest_files:
        raise ValueError(f"File referenced in fixity block not found in manifest: {fixity['file']}")

    # Validate checksum method
    allowed_methods = {'md5', 'sha1', 'sha256'}
    if fixity['method'] not in allowed_methods:
        raise ValueError(f"Invalid checksum method in fixity block: {fixity['method']}")

    return True

