def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """

    def validate_object(obj):
        if validate_objects:
            if obj.is_valid(show_warnings):
                return True
        if check_digests and hasattr(obj, 'digest') and obj.digest is not None:
            if obj.digest != obj.compute_digest():
                raise DigestMismatchError(f"Digest mismatch for object {obj.id}")
        return False

    def validate_subtree(subtree, parent=None):
        num_objects = 0
        good_objects = 0
        for obj in subtree:
            num_objects += 1
            if validate_object(obj):
                good_objects += 1
            if hasattr(obj, 'subtree'):
                sub_num, sub_good = validate_subtree(obj.subtree, obj)
                num_objects += sub_num
                good_objects += sub_good
        return num_objects, good_objects

    return validate_subtree(self)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        num = int(version)
        return str(num + 1)
    except ValueError:
        parts = version.lstrip('vV').split('.')
        num_parts = [int(part) for part in parts if part.isdigit()]
        if num_parts:
            last_num = max(num_parts)
            last_part_index = version.rfind(str(last_num))
            return version[:last_part_index] + str(last_num + 1)
        else:
            return version + '.1'

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = None
    content_digests = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.json')
        with open(inventory_path, 'r') as f:
            inventory = json.load(f)

        if root_inventory is None:
            root_inventory = inventory
        else:
            validate_inventory(root_inventory, inventory)

        for content_path, digest in inventory['content_digests'].items():
            if content_path not in content_digests:
                content_digests[content_path] = digest
            elif content_digests[content_path] != digest:
                raise ContentDigestMismatch(content_path, content_digests[content_path], digest)

    return content_digests

