def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    if not all(isinstance(a, str) for a in alphabet):
        raise ValueError("Alphabet must be a list of strings")

    if number < 0:
        raise ValueError("Number must be non-negative")

    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Padding must be a non-negative integer")

    if number == 0:
        if padding is not None:
            return ''.join(alphabet[0] for _ in range(padding))
        return alphabet[0]

    digits = []
    while number > 0:
        digits.append(number % len(alphabet))
        number //= len(alphabet)

    result = ''.join(alphabet[d] for d in reversed(digits))

    if padding is not None:
        result = result.zfill(padding)

    return result

