def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """

    import ast
    from logging import LogRecord

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config_content = file.read()
                if resolve_env:
                    import os
                    config_content = os.path.expandvars(config_content)
                try:
                    config_dict[filename] = ast.literal_eval(config_content)
                except (ValueError, SyntaxError) as e:
                    log_record = LogRecord('config_module', logging.ERROR, filename, None, f"Error parsing {filename}: {e}", None, None)
                    log_records.append(log_record)
        except FileNotFoundError:
            log_record = LogRecord('config_module', logging.ERROR, filename, None, f"File {filename} not found.", None, None)
            log_records.append(log_record)
        except Exception as e:
            log_record = LogRecord('config_module', logging.ERROR, filename, None, f"Unexpected error reading {filename}: {e}", None, None)
            log_records.append(log_record)

    if overrides:
        for filename, overrides_dict in overrides.items():
            if filename in config_dict:
                config_dict[filename].update(overrides_dict)
            else:
                log_record = LogRecord('config_module', logging.WARNING, filename, None, f"No configuration found for specified overrides in {filename}.", None, None)
                log_records.append(log_record)

    return config_dict, log_records

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        return [], type(None)

    if not hasattr(seq, '__len__') or not hasattr(seq, '__getitem__') or not hasattr(seq, '__iter__'):
        return [seq], type(seq)

    if bufsize is not None and isinstance(bufsize, int) and bufsize > 0:
