def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    import yaml
    from irvalidator import IRValidatorException

    if spec_content is None:
        raise ValueError("spec_content cannot be None")

    try:
        spec_dict = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Invalid YAML content: {e}")

    required_fields = cls.REQUIRED_FIELDS  # Assuming REQUIRED_FIELDS is a class variable

    for field in required_fields:
        if field not in spec_dict:
            raise IRValidatorException(f"Required field '{field}' is missing in spec file")

    return spec_dict

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    import yaml

    if yaml_file is None:
        raise ValueError("YAML file path must be provided")

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)
    except FileNotFoundError:
        raise FileNotFoundError(f"YAML file not found: {yaml_file}")
    except yaml.YAMLError as e:
        raise ValueError(f"Error parsing YAML file: {e}")

    # Validate required fields here
    required_fields = ['id', 'label', 'description']
    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"Required field '{field}' is missing in YAML file")

    return data

