def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if not isinstance(arg, (int, float)):
            raise ValueError(f"Argument {arg} is not a number.")
        if len(arg) != 3:
            raise ValueError(f"Argument {arg} does not have exactly three elements.")
        min_val, value, max_val = arg
        if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)):
            raise ValueError(f"Min and max values {min_val} and {max_val} are not numbers.")
