def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments
    """
    if not isinstance(parser_name, str):
        raise TypeError("parser_name must be a string")
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    for key, value in values_dict.items():
        if key not in parser_cmd_metadata[parser_name]:
            continue  # Skip unknown arguments

        metadata = parser_cmd_metadata[parser_name][key]
        if metadata['type'] == 'integer':
            values_dict[key] = int(value)
        elif metadata['type'] == 'boolean':
            values_dict[key] = value.lower() in ['true', '1', 't', 'y', 'yes']
        elif metadata['type'] == 'float':
            values_dict[key] = float(value)
        elif metadata['type'] == 'list':
            values_dict[key] = value.split(metadata['delimiter'])

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    plugin_spec_path = os.path.join(plugin_dir, 'plugin_spec.json')

    if not os.path.exists(plugin_spec_path):
        raise FileNotFoundError(f"Plugin spec file not found at {plugin_spec_path}")

    with open(plugin_spec_path, 'r') as f:
        spec = json.load(f)

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec)

